package dev.starfold;

import dev.starfold.BentStripGeometry.Point;
import dev.starfold.CubeSurfaceTopology.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class GroundOrbitTest {
    private GroundSpace.Pose pose(Face f,double u,double h,double v){return new GroundSpace.Pose(f,new Point(u,h,v));}
    @Test void acceptedBandAndIndependentOrbitBandDoNotOverlap(){assertEquals(new GroundAir.Config(30,128),GroundAir.DEFAULT);assertEquals(new GroundSpace.Config(16,128),GroundSpace.DEFAULT_MASK);assertEquals(0,GroundOrbit.weight(128.72));assertEquals(0,GroundOrbit.weight(160));assertEquals(1,GroundOrbit.weight(1024));assertEquals(32768,GroundSpace.CEILING);}
    @Test void allFacesHaveReversibleFlightAddresses(){for(var f:Face.values())for(double u:new double[]{.001,16.5,1024,2047.999})for(double v:new double[]{.001,1024,2047.999})for(double h:new double[]{.94,128,160,1024,20000,32767}){var p=pose(f,u,h,v);var q=GroundOrbit.locate(GroundOrbit.position(p));assertEquals(f,q.face());assertTrue(p.point().sub(q.point()).length()<1e-8);}}
    @Test void invalidFlightShellAndNaNsAreRejected(){assertThrows(IllegalArgumentException.class,()->GroundOrbit.locate(new Point(0,0,0)));assertThrows(IllegalArgumentException.class,()->GroundOrbit.locate(new Point(Double.NaN,1,1)));assertThrows(IllegalArgumentException.class,()->GroundOrbit.locate(new Point(0,GroundOrbit.RADIUS+32769,0)));}
    @Test void startMatchesAcceptedPlanarMapIncludingFineGridVertices(){for(var f:Face.values())for(var eye:List.of(new Point(20.5,160,2.5),new Point(1024,160,.1),new Point(1000.5,160,1000.5))){var p=pose(f,eye.x(),159.28,eye.z());var orbit=new GroundOrbit(p,eye,256);var air=new GroundAir(f,eye,GroundAir.DEFAULT,true);var chart=new GroundChart(f);for(var tile:chart.tiles())for(int a=-256;a<=256;a+=23)for(int b=-256;b<=256;b+=29){var local=tile.local(new Point(eye.x()+a,0,eye.z()+b));if(local.x()<0||local.z()<0||local.x()>2048||local.z()>2048)continue;var flat=tile.point(local);if(air.facing(flat)<0)continue;assertTrue(air.flat(flat).sub(orbit.point(tile.face(),local)).length()<1e-7,f+" "+eye+" "+local);}}}
    @Test void everySharedEdgeWeldsThroughAllOrbitalHeights(){int checked=0;for(var root:Face.values())for(double height:new double[]{160,256,512,1024,4096}){var eye=new Point(800.5,height,900.5);var m=new GroundOrbit(pose(root,800.5,height-.72,900.5),eye,256);for(var f:Face.values())for(int edge=0;edge<4;edge++)for(double t:new double[]{0,16,500.25,1024,2048})for(double h:new double[]{0,55,128}){double u=edge==0?0:edge==1?2048:t,v=edge==2?0:edge==3?2048:t;var s=GroundOrbit.direction(f,u,v);Face other=null;for(var a:Face.values())if(a!=f&&Math.abs(s.dot(a.normal)-s.dot(f.normal))<1e-9){other=a;break;}assertNotNull(other);double scale=1024/s.dot(other.normal);var q=new Point(1024+s.dot(other.u)*scale,h,1024+s.dot(other.v)*scale);var a=m.point(f,new Point(u,h,v));var b=m.point(other,q);if(s.dot(m.normal)>m.minimumFacing+.01)assertTrue(a.sub(b).length()<1e-5,"weld "+f+" "+other+" "+height);checked++;}}assertEquals(10800,checked);}
    @Test void fullExteriorIsAnActualClosedSphereNotADisk(){var eye=new Point(1000.5,4096,900.5);var m=new GroundOrbit(pose(Face.TOP,eye.x(),4095.28,eye.z()),eye,128);var center=new Point(eye.x(),-GroundOrbit.RADIUS,eye.z());assertTrue(Double.isInfinite(m.clip));assertEquals(-1,m.minimumFacing);for(var f:Face.values())for(double u:new double[]{0,512,1024,2048})for(double v:new double[]{0,512,1024,2048})for(double h:new double[]{0,55,128})assertEquals(GroundOrbit.RADIUS+h,m.raw(f,new Point(u,h,v)).sub(center).length(),1e-8);}
    @Test void tangentFramesAreOrthonormalAndRespectSeamTransport(){for(var f:Face.values())for(var p:List.of(new Point(0,200,0),new Point(.01,1024,800),new Point(1024,4096,1024))){var frame=GroundOrbit.frame(new GroundSpace.Pose(f,p));assertEquals(1,frame.u().length(),1e-10);assertEquals(1,frame.up().length(),1e-10);assertEquals(1,frame.v().length(),1e-10);assertEquals(0,frame.u().dot(frame.v()),1e-10);assertTrue(frame.u().cross(frame.up()).sub(frame.v()).length()<1e-10);var d=new Point(.3,.5,.7);assertTrue(d.sub(frame.local(frame.world(d))).length()<1e-10);}}
}
